/**
 * Auto-discover Eagle Library (.library) in Vault or surrounding directories
 */
function discoverEagleLibraryPath(app) {
  try {
    const vaultPath = app?.vault?.adapter?.basePath || (app?.vault?.adapter?.getBasePath ? app.vault.adapter.getBasePath() : '');
    if (vaultPath) {
      // 1. Check in Vault root
      if (fs.existsSync(vaultPath)) {
        const entries = fs.readdirSync(vaultPath);
        for (const entry of entries) {
          if (entry.endsWith('.library') || entry.includes('.library')) {
            const candidate = path.join(vaultPath, entry, 'images');
            if (fs.existsSync(candidate)) return candidate;
          }
        }
      }
      // 2. Check in Vault parent directory
      const parentDir = path.dirname(vaultPath);
      if (fs.existsSync(parentDir)) {
        const parentEntries = fs.readdirSync(parentDir);
        for (const entry of parentEntries) {
          if (entry.endsWith('.library') || entry.includes('.library')) {
            const candidate = path.join(parentDir, entry, 'images');
            if (fs.existsSync(candidate)) return candidate;
          }
        }
      }
    }
    // 3. Check User standard Pictures directory
    const home = process.env.HOME || process.env.USERPROFILE || '';
    if (home) {
      const picDir = path.join(home, 'Pictures');
      if (fs.existsSync(picDir)) {
        const picEntries = fs.readdirSync(picDir);
        for (const entry of picEntries) {
          if (entry.endsWith('.library') || entry.includes('.library')) {
            const candidate = path.join(picDir, entry, 'images');
            if (fs.existsSync(candidate)) return candidate;
          }
        }
      }
    }
  } catch (e) {}
  return '';
}

/**
 * Robust MIME type detection by in-memory magic bytes & extension
 */
function getMimeType(buffer, ext) {
  if (buffer && buffer.length >= 12) {
    if (buffer.slice(0, 4).toString('ascii') === 'RIFF' && buffer.slice(8, 12).toString('ascii') === 'WEBP') {
      return 'image/webp';
    }
    if (buffer[0] === 0x89 && buffer[1] === 0x50 && buffer[2] === 0x4E && buffer[3] === 0x47) {
      return 'image/png';
    }
    if (buffer[0] === 0xFF && buffer[1] === 0xD8 && buffer[2] === 0xFF) {
      return 'image/jpeg';
    }
    if (buffer.slice(0, 3).toString('ascii') === 'GIF') {
      return 'image/gif';
    }
  }

  const map = {
    'jpg': 'image/jpeg',
    'jpeg': 'image/jpeg',
    'png': 'image/png',
    'gif': 'image/gif',
    'svg': 'image/svg+xml',
    'webp': 'image/webp',
    'mp4': 'video/mp4'
  };
  return map[(ext || '').toLowerCase()] || 'image/jpeg';
}

/**
 * Safe Base64 Image Loader for Electron / Obsidian
 */
function attachImageSrc(imgEl, filePath, ext) {
  if (!filePath || !fs.existsSync(filePath)) return;

  fs.promises.readFile(filePath)
    .then(buffer => {
      const mime = getMimeType(buffer, ext);
      imgEl.src = `data:${mime};base64,${buffer.toString('base64')}`;
    })
    .catch(err => {
      console.error('[Crisp Visual] Failed to read image file:', filePath, err);
    });
}

function getImageDimensionsFromBuffer(buffer, ext) {
  try {
    const e = (ext || '').toLowerCase();
    if (e === 'png' && buffer.length > 24) {
      if (buffer[0] === 0x89 && buffer[1] === 0x50 && buffer[2] === 0x4E && buffer[3] === 0x47) {
        return {
          width: buffer.readUInt32BE(16),
          height: buffer.readUInt32BE(20)
        };
      }
    }
    if ((e === 'jpg' || e === 'jpeg') && buffer.length > 2) {
      let offset = 2;
      while (offset < buffer.length - 8) {
        if (buffer[offset] === 0xFF) {
          const marker = buffer[offset + 1];
          if ((marker >= 0xC0 && marker <= 0xC3) || (marker >= 0xC5 && marker <= 0xC7) || (marker >= 0xC9 && marker <= 0xCB) || (marker >= 0xCD && marker <= 0xCF)) {
            const height = buffer.readUInt16BE(offset + 5);
            const width = buffer.readUInt16BE(offset + 7);
            return { width, height };
          }
          const length = buffer.readUInt16BE(offset + 2);
          offset += 2 + length;
        } else {
          offset++;
        }
      }
    }
    if (e === 'gif' && buffer.length > 10) {
      return {
        width: buffer.readUInt16LE(6),
        height: buffer.readUInt16LE(8)
      };
    }
  } catch (e) {}
  return { width: 0, height: 0 };
}

function getOcrBinaryPath(app) {
  try {
    const basePath = app?.vault?.adapter?.basePath || (app?.vault?.adapter?.getBasePath ? app.vault.adapter.getBasePath() : '');
    if (basePath) {
      const p = path.join(basePath, '.obsidian', 'plugins', 'crisp-visual', 'vision_ocr');
      if (fs.existsSync(p)) return p;
    }
  } catch (e) {}
  const localPluginPath = path.join(__dirname, 'vision_ocr');
  if (fs.existsSync(localPluginPath)) return localPluginPath;
  return null;
}

/**
 * Robust Multi-strategy Clipboard Image Reader
 */
async function readClipboardImageBuffer() {
  // Strategy 1: Web Clipboard API (Standard Chromium / Electron)
  try {
    if (navigator.clipboard && navigator.clipboard.read) {
      const items = await navigator.clipboard.read();
      for (const item of items) {
        for (const type of item.types) {
          if (type.startsWith('image/')) {
            const blob = await item.getType(type);
            const arrayBuffer = await blob.arrayBuffer();
            return Buffer.from(arrayBuffer);
          }
        }
      }
    }
  } catch (e) {
    // Strategy 1 failed, fallback to next
  }

  // Strategy 2: Electron Native Clipboard
  try {
    let electronClipboard = null;
    if (typeof window !== 'undefined' && window.require) {
      electronClipboard = window.require('electron').clipboard;
    } else {
      electronClipboard = require('electron').clipboard;
    }
    if (electronClipboard) {
      const img = electronClipboard.readImage();
      if (img && !img.isEmpty()) {
        return img.toPNG();
      }
    }
  } catch (e) {}

  // Strategy 3: macOS Native AppleScript Dump (100% reliable on macOS)
  if (process.platform === 'darwin') {
    return new Promise((resolve) => {
      const tmpFile = `/tmp/crisp_clipboard_${Date.now()}.png`;
      const script = `
        try
          set theFile to open for access POSIX file "${tmpFile}" with write permission
          set eof theFile to 0
          write (the clipboard as «class PNGf») to theFile
          close access theFile
          return "OK"
        on error errMsg
          return "ERR:" & errMsg
        end try
      `;
      exec(`osascript -e '${script.replace(/'/g, "'\\''")}'`, (err, stdout) => {
        if (!err && fs.existsSync(tmpFile)) {
          const buf = fs.readFileSync(tmpFile);
          try { fs.unlinkSync(tmpFile); } catch (e) {}
          if (buf && buf.length > 100) {
            resolve(buf);
            return;
          }
        }
        resolve(null);
      });
    });
  }

  return null;
}

/**
 * Color classifier utility
 */
function classifyRGB(r, g, b) {
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const l = (max + min) / 2 / 255;
  const d = (max - min) / 255;

  if (l < 0.15) return 'dark';
  if (l > 0.88 && d < 0.12) return 'light';
  if (d < 0.1) return 'gray';

  let h = 0;
  if (max === r) h = ((g - b) / 255) / d % 6;
  else if (max === g) h = ((b - r) / 255) / d + 2;
  else h = ((r - g) / 255) / d + 4;
  h = Math.round(h * 60);
  if (h < 0) h += 360;

  if (h >= 345 || h < 15) return 'red';
  if (h >= 15 && h < 45) return 'orange';
  if (h >= 45 && h < 70) return 'yellow';
  if (h >= 70 && h < 165) return 'green';
  if (h >= 165 && h < 200) return 'cyan';
  if (h >= 200 && h < 265) return 'blue';
  if (h >= 265 && h < 345) return 'purple';
  return 'other';
}

function rgbToHex(r, g, b) {
  return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1).toUpperCase();
}

function generateEagleId() {
  const chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  let result = 'MT' + Date.now().toString(36).toUpperCase().slice(-4);
  while (result.length < 13) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
}

const FOLDER_COLOR_MAP = {
  blue: '#3b82f6',
  yellow: '#eab308',
  green: '#22c55e',
  purple: '#a855f7',
  red: '#ef4444',
  gray: '#9ca3af'
};

/**
 * Media Scanner Engine for Eagle Library & Local Asset Folders
 */
class MediaScanner {
  constructor(plugin) {
    this.plugin = plugin;
    this.items = [];
    this.folders = [];
    this.folderMap = new Map();
    this.parentMap = new Map();
  }

  async scan() {
    const rootPath = this.plugin.settings.mediaRoot;
    this.items = [];
    this.folders = [];
    this.folderMap.clear();
    this.parentMap.clear();

    if (!fs.existsSync(rootPath)) {
      console.warn(`[Crisp Visual] Media root path does not exist: ${rootPath}`);
      return [];
    }

    try {
      // 1. Read Eagle library parent metadata.json for full folder tree
      const libRoot = path.resolve(rootPath, '..');
      const eagleLibInfo = path.join(libRoot, 'metadata.json');
      if (fs.existsSync(eagleLibInfo)) {
        try {
          const libMeta = JSON.parse(fs.readFileSync(eagleLibInfo, 'utf-8'));
          if (libMeta.folders) {
            this.folders = libMeta.folders;
            const traverse = (list, parentId = null) => {
              for (const f of list) {
                this.folderMap.set(f.id, f);
                if (parentId) this.parentMap.set(f.id, parentId);
                if (f.children && f.children.length > 0) {
                  traverse(f.children, f.id);
                }
              }
            };
            traverse(this.folders);
          }
        } catch (e) {
          console.warn('[Crisp Visual] Failed to parse library metadata:', e);
        }
      }

      // Helper to compute all ancestor folder IDs
      const getAncestors = (folderId) => {
        const ancestors = [folderId];
        let cur = folderId;
        while (this.parentMap.has(cur)) {
          cur = this.parentMap.get(cur);
          ancestors.push(cur);
        }
        return ancestors;
      };

      // 2. Scan images folder
      const entries = fs.readdirSync(rootPath, { withFileTypes: true });

      for (const entry of entries) {
        if (!entry.isDirectory()) continue;

        if (entry.name.endsWith('.info')) {
          // Eagle Item structure: <id>.info
          const infoDir = path.join(rootPath, entry.name);
          const metaPath = path.join(infoDir, 'metadata.json');
          if (!fs.existsSync(metaPath)) continue;

          try {
            const meta = JSON.parse(fs.readFileSync(metaPath, 'utf-8'));
            const files = fs.readdirSync(infoDir);
            
            let mainFile = null;
            let thumbFile = null;
            for (const f of files) {
              if (f === 'metadata.json') continue;
              if (f.includes('_thumbnail.')) thumbFile = path.join(infoDir, f);
              else if (!mainFile) mainFile = path.join(infoDir, f);
            }

            if (!mainFile) continue;

            const ext = meta.ext || path.extname(mainFile).slice(1).toLowerCase();
            const id = meta.id || entry.name.replace('.info', '');
            const name = meta.name || path.basename(mainFile, path.extname(mainFile));

            let primaryColorGroup = 'other';
            let primaryHex = '#888888';
            if (meta.palettes && meta.palettes.length > 0) {
              const p = meta.palettes[0];
              if (p.color && p.color.length === 3) {
                primaryHex = rgbToHex(p.color[0], p.color[1], p.color[2]);
                primaryColorGroup = classifyRGB(p.color[0], p.color[1], p.color[2]);
              }
            }

            const directFolders = meta.folders || [];
            const allFolderIds = new Set();
            for (const fid of directFolders) {
              const ancestors = getAncestors(fid);
              ancestors.forEach(a => allFolderIds.add(a));
            }

            const item = {
              id: id,
              name: name,
              ext: ext,
              size: meta.size || fs.statSync(mainFile).size,
              width: meta.width || 0,
              height: meta.height || 0,
              filePath: mainFile,
              thumbnailPath: thumbFile || mainFile,
              tags: meta.tags || [],
              folders: directFolders,
              allFolderIds: allFolderIds,
              foldersNamed: directFolders.map(fid => this.folderMap.get(fid)?.name || fid),
              annotation: meta.annotation || '',
              ocrText: meta.ocrText || meta.annotation || '',
              star: meta.star || 0,
              rating: meta.star || 0,
              url: meta.url || '',
              mtime: meta.mtime || meta.modificationTime || Date.now(),
              palettes: meta.palettes || [],
              primaryColorGroup: primaryColorGroup,
              primaryHex: primaryHex,
              eagleUri: `eagle://item/${id}`,
              metaPath: metaPath
            };

            this.items.push(item);
          } catch (err) {
            console.error(`[Crisp Visual] Error reading item ${entry.name}:`, err);
          }
        }
      }

      this.items.sort((a, b) => b.mtime - a.mtime);
      return this.items;
    } catch (e) {
      console.error('[Crisp Visual] Scan failed:', e);
      return [];
    }
  }

  async runOCR(item) {
    if (!this.plugin.licenseManager || !this.plugin.licenseManager.isEntitled()) {
      return null;
    }

    const ocrBinary = getOcrBinaryPath(this.plugin.app);
    if (!ocrBinary || !fs.existsSync(ocrBinary)) {
      console.warn('[Crisp Visual] OCR binary not found at:', ocrBinary);
      return null;
    }

    return new Promise((resolve) => {
      execFile(ocrBinary, [item.filePath], { timeout: 10000 }, (error, stdout) => {
        if (error) {
          console.warn('[Crisp Visual] OCR error:', error);
          resolve(null);
          return;
        }
        const text = (stdout || '').trim();
        if (text) {
          try {
            const meta = JSON.parse(fs.readFileSync(item.metaPath, 'utf-8'));
            meta.ocrText = text;
            if (!meta.annotation) meta.annotation = text;
            fs.writeFileSync(item.metaPath, JSON.stringify(meta, null, 2), 'utf-8');
            item.ocrText = text;
            item.annotation = meta.annotation;
            resolve(text);
          } catch (e) {
            resolve(text);
          }
        } else {
          resolve(null);
        }
      });
    });
  }

  async updateItemStar(item, star) {
    if (!this.plugin.licenseManager || !this.plugin.licenseManager.isEntitled()) {
      return false;
    }
    try {
      const meta = JSON.parse(fs.readFileSync(item.metaPath, 'utf-8'));
      meta.star = star;
      fs.writeFileSync(item.metaPath, JSON.stringify(meta, null, 2), 'utf-8');
      item.star = star;
      item.rating = star;
      return true;
    } catch (e) {
      console.error('[Crisp Visual] Failed to update star rating:', e);
      return false;
    }
  }

  async ingestBuffer(buffer, name, folderId = null, ext = 'png') {
    const rootPath = this.plugin.settings.mediaRoot;
    const id = generateEagleId();
    const infoDir = path.join(rootPath, `${id}.info`);
    fs.mkdirSync(infoDir, { recursive: true });

    const safeName = (name || `CAP-${new Date().toISOString().slice(0, 10)}-${Date.now().toString().slice(-4)}`).replace(/[\\/:*?"<>|]/g, '_');
    const mainFile = path.join(infoDir, `${safeName}.${ext}`);
    const thumbFile = path.join(infoDir, `${safeName}_thumbnail.png`);

    fs.writeFileSync(mainFile, buffer);
    fs.writeFileSync(thumbFile, buffer);

    const targetFolders = folderId && folderId !== 'all' && folderId !== 'uncategorized' 
      ? [folderId] 
      : ['MT1AJUK1N8Q0N'];

    const dimensions = getImageDimensionsFromBuffer(buffer, ext);

    const meta = {
      id: id,
      name: safeName,
      size: buffer.length,
      btime: Date.now(),
      mtime: Date.now(),
      ext: ext,
      tags: ['clipboard'],
      folders: targetFolders,
      isDeleted: false,
      url: '',
      annotation: '',
      modificationTime: Date.now(),
      height: dimensions.height || 0,
      width: dimensions.width || 0,
      star: 0,
      palettes: []
    };

    const metaPath = path.join(infoDir, 'metadata.json');
    fs.writeFileSync(metaPath, JSON.stringify(meta, null, 2), 'utf-8');

    return { id, name: safeName, mainFile, metaPath };
  }
}

/**
 * Real-time File System Watcher for Eagle Library
 */
class LibraryWatcher {
  constructor(plugin, onChange) {
    this.plugin = plugin;
    this.onChange = onChange;
    this.watchers = [];
    this.debounceTimer = null;
  }

  start() {
    this.stop();
    const rootPath = this.plugin.settings.mediaRoot;
    if (!fs.existsSync(rootPath)) return;

    const trigger = () => {
      if (this.debounceTimer) clearTimeout(this.debounceTimer);
      this.debounceTimer = setTimeout(() => {
        if (this.onChange) this.onChange();
      }, 400);
    };

    try {
      const w1 = fs.watch(rootPath, { recursive: false }, () => trigger());
      this.watchers.push(w1);

      const libRoot = path.resolve(rootPath, '..');
      const metaPath = path.join(libRoot, 'metadata.json');
      if (fs.existsSync(metaPath)) {
        const w2 = fs.watch(metaPath, () => trigger());
        this.watchers.push(w2);
      }
    } catch (e) {
      console.warn('[Crisp Visual] File watcher error:', e);
    }
  }

  stop() {
    if (this.debounceTimer) {
      clearTimeout(this.debounceTimer);
      this.debounceTimer = null;
    }
    for (const w of this.watchers) {
      try { w.close(); } catch (e) {}
    }
    this.watchers = [];
  }
}

/**
 * Main Crisp Visual View (Apple Aesthetic Masonry Gallery)
 */
class CrispVisualView extends ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    this.plugin = plugin;
    this.scanner = new MediaScanner(plugin);
    this.watcher = new LibraryWatcher(plugin, () => {
      this.refresh(true);
    });
    this.filteredItems = [];
    this.searchQuery = '';
    this.selectedColor = 'all';
    this.selectedFormat = 'all';
    this.selectedRatio = 'all';
    this.selectedStar = 'all';
    this.selectedFolderId = 'all';
    this.selectedTag = null;
    this.expandedFolders = new Set();
    this.isSidebarCollapsed = false;
    this.isFoldersCollapsed = false;
    this.isTagsCollapsed = false;
    this.isGrayscaleMode = false;
    this.densityMode = this.plugin.settings.densityMode || 'standard';
  }

  getViewType() {
    return CRISP_VISUAL_VIEW_TYPE;
  }

  getDisplayText() {
    return 'Crisp Visual';
  }

  getIcon() {
    return 'crisp-visual-icon';
  }

  async onOpen() {
    await this.refresh();
    this.watcher.start();

    // Listen for clipboard paste on container
    this.pasteHandler = (e) => this.handlePaste(e);
    this.containerEl.addEventListener('paste', this.pasteHandler);
    
    // Drag-in file support
    this.containerEl.addEventListener('dragover', (e) => e.preventDefault());
    this.containerEl.addEventListener('drop', (e) => this.handleDrop(e));
  }

  async onClose() {
    this.watcher.stop();
    if (this.pasteHandler) {
      this.containerEl.removeEventListener('paste', this.pasteHandler);
    }
  }

  async handlePaste(e) {
    if (!this.plugin.licenseManager || !this.plugin.licenseManager.isEntitled()) {
      new Notice('🔒 剪贴板秒存入库为 Crisp Pro 专业版功能');
      new CrispVisualActivationModal(this.app, this.plugin, () => this.refresh()).open();
      return;
    }

    try {
      new Notice('📥 [Crisp Visual] 正在读取剪贴板...');
      const buffer = await readClipboardImageBuffer();
      if (buffer && buffer.length > 100) {
        const res = await this.scanner.ingestBuffer(buffer, null, this.selectedFolderId, 'png');
        new Notice(`🎉 [Crisp Visual] 剪贴板素材已秒存入库：${res.name}`);
        await this.refresh();

        // Background OCR
        setTimeout(async () => {
          const item = this.items.find(i => i.id === res.id);
          if (item) {
            const ocr = await this.scanner.runOCR(item);
            if (ocr) new Notice(`🔍 [OCR] 已自动提取文案并建立即席搜索索引！`);
          }
        }, 500);
      } else {
        new Notice('⚠️ 剪贴板中未检测到图片或截图数据');
      }
    } catch (err) {
      console.warn('[Crisp Visual] Paste error:', err);
      new Notice(`❌ 粘贴入库失败: ${err.message}`);
    }
  }

  async handleDrop(e) {
    e.preventDefault();
    if (!this.plugin.licenseManager || !this.plugin.licenseManager.isEntitled()) {
      new Notice('🔒 拖拽快速存图为 Crisp Pro 专业版功能');
      new CrispVisualActivationModal(this.app, this.plugin, () => this.refresh()).open();
      return;
    }

    if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      let imported = 0;
      for (const file of e.dataTransfer.files) {
        const ext = path.extname(file.path).slice(1).toLowerCase();
        if (['png', 'jpg', 'jpeg', 'gif', 'svg', 'webp'].includes(ext)) {
          const buf = fs.readFileSync(file.path);
          const baseName = path.basename(file.path, path.extname(file.path));
          await this.scanner.ingestBuffer(buf, baseName, this.selectedFolderId, ext);
          imported++;
        }
      }
      if (imported > 0) {
        new Notice(`🎉 [Crisp Visual] 已成功导入 ${imported} 张外部素材！`);
        await this.refresh();
      }
    }
  }

  async refresh(isSilent = false) {
    this.items = await this.scanner.scan();
    if (this.scanner.folders) {
      for (const f of this.scanner.folders) {
        if (f.children && f.children.length > 0) {
          this.expandedFolders.add(f.id);
        }
      }
    }
    this.applyFilters();
    this.render();
  }

  applyFilters() {
    const isPro = this.plugin.licenseManager && this.plugin.licenseManager.isEntitled();
    const result = this.items.filter(item => {
      // 1. Search Query Filter (Name + Tags + Folders + OCR Text + Annotation + Ext)
      if (this.searchQuery) {
        const q = this.searchQuery.toLowerCase().trim();
        const matchName = item.name.toLowerCase().includes(q);
        const matchTag = (item.tags || []).some(t => t.toLowerCase().includes(q));
        const matchFolder = (item.foldersNamed || []).some(f => f.toLowerCase().includes(q));
        const matchAnnotation = (item.annotation || '').toLowerCase().includes(q);
        const matchExt = (item.ext || '').toLowerCase() === q;
        const matchOcr = (isPro && (item.ocrText || '').toLowerCase().includes(q));
        if (!matchName && !matchTag && !matchFolder && !matchAnnotation && !matchExt && !matchOcr) return false;
      }

      // 2. Color Filter
      if (this.selectedColor !== 'all') {
        if (item.primaryColorGroup !== this.selectedColor) return false;
      }

      // 3. Format Filter (Normalizing jpg and jpeg)
      if (this.selectedFormat !== 'all') {
        const itemExt = item.ext.toLowerCase() === 'jpeg' ? 'jpg' : item.ext.toLowerCase();
        const selFmt = this.selectedFormat.toLowerCase() === 'jpeg' ? 'jpg' : this.selectedFormat.toLowerCase();
        if (itemExt !== selFmt) return false;
      }

      // 4. Aspect Ratio Filter
      if (this.selectedRatio !== 'all') {
        const r = (item.width && item.height) ? (item.width / item.height) : 1;
        if (this.selectedRatio === '1:1') {
          if (r < 0.92 || r > 1.08) return false;
        } else if (this.selectedRatio === '3:4') {
          if (r < 0.68 || r > 0.82) return false;
        } else if (this.selectedRatio === '4:3') {
          if (r < 1.25 || r > 1.45) return false;
        } else if (this.selectedRatio === '9:16') {
          if (r < 0.50 || r > 0.65) return false;
        } else if (this.selectedRatio === '16:9') {
          if (r < 1.65 || r > 1.95) return false;
        } else if (this.selectedRatio === 'banner') {
          if (r < 1.95) return false;
        } else if (this.selectedRatio === 'long') {
          if (r >= 0.50) return false;
        } else if (this.selectedRatio === 'other') {
          const isStandard = (
            (r >= 0.92 && r <= 1.08) ||
            (r >= 0.68 && r <= 0.82) ||
            (r >= 1.25 && r <= 1.45) ||
            (r >= 0.50 && r <= 0.65) ||
            (r >= 1.65 && r <= 1.95) ||
            (r >= 1.95) ||
            (r < 0.50)
          );
          if (isStandard) return false;
        }
      }

      // 5. Star Rating Filter
      if (this.selectedStar !== 'all') {
        const minStar = parseInt(this.selectedStar);
        if ((item.star || 0) < minStar) return false;
      }

      // 6. Folder / Ancestry Filter
      if (this.selectedFolderId !== 'all') {
        if (this.selectedFolderId === 'uncategorized') {
          if (item.folders && item.folders.length > 0) return false;
        } else {
          if (!item.allFolderIds || !item.allFolderIds.has(this.selectedFolderId)) return false;
        }
      }

      // 7. Tag Filter
      if (this.selectedTag) {
        if (!item.tags || !item.tags.includes(this.selectedTag)) return false;
      }

      return true;
    });

    this.totalFilteredCount = result.length;
    if (!isPro && result.length > 20) {
      this.filteredItems = result.slice(0, 20);
      this.isFreeCapped = true;
    } else {
      this.filteredItems = result;
      this.isFreeCapped = false;
    }
  }

  render() {
    const container = this.containerEl.children[1];
    container.empty();
    container.addClass('crisp-visual-container');

    // 1. Header Bar
    const header = container.createDiv({ cls: 'crisp-visual-header' });
    
    // Left: Toggle Sidebar + Title badge & Search
    const leftHeader = header.createDiv({ cls: 'crisp-visual-header-left' });
    
    const toggleBtn = leftHeader.createEl('button', {
      cls: `crisp-visual-toggle-sidebar-btn ${this.isSidebarCollapsed ? 'collapsed' : ''}`,
      title: this.isSidebarCollapsed ? '展开目录栏' : '收起目录栏'
    });
    toggleBtn.innerHTML = `<svg viewBox="1.5 4.5 21 15" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12L5 12M22 12L19 12M14 12L10 12"/><path d="M5 13L5 7.5C5 6.56538 5 6.09808 5.20096 5.75C5.33261 5.52197 5.52197 5.33261 5.75 5.20096C6.09808 5 6.56538 5 7.5 5C8.43462 5 8.90192 5 9.25 5.20096C9.47803 5.33261 9.66739 5.52197 9.79904 5.75C10 6.09808 10 6.56538 10 7.5L10 16.5C10 17.4346 10 17.9019 9.79904 18.25C9.66739 18.478 9.47803 18.6674 9.25 18.799C8.90192 19 8.43462 19 7.5 19C6.56538 19 6.09808 19 5.75 18.799C5.52197 18.6674 5.33261 18.478 5.20096 18.25C5.03954 17.9704 5.00778 17.6139 5.00153 17"/><path d="M16.5 7C15.5654 7 15.0981 7 14.75 7.20096C14.522 7.33261 14.3326 7.52197 14.201 7.75C14 8.09808 14 8.56538 14 9.5L14 14.5C14 15.4346 14 15.9019 14.201 16.25C14.3326 16.478 14.522 16.6674 14.75 16.799C15.0981 17 15.5654 17 16.5 17C17.4346 17 17.9019 17 18.25 16.799C18.478 16.6674 18.6674 16.478 18.799 16.25C19 15.9019 19 15.4346 19 14.5V9.5C19 8.56538 19 8.09808 18.799 7.75C18.6674 7.52197 18.478 7.33261 18.25 7.20096C17.9019 7 17.4346 7 16.5 7Z"/></svg>`;
    toggleBtn.addEventListener('click', () => {
      this.isSidebarCollapsed = !this.isSidebarCollapsed;
      this.render();
    });

    const titleBadge = leftHeader.createDiv({ cls: 'crisp-visual-title-badge' });
    titleBadge.innerHTML = `${CRISP_VISUAL_SVG}<span>Crisp Visual</span>`;

    const searchWrap = leftHeader.createDiv({ cls: 'crisp-visual-search-box' });
    searchWrap.innerHTML = `<svg class="crisp-visual-search-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/></svg>`;
    const searchInput = searchWrap.createEl('input', {
      cls: 'crisp-visual-search-input',
      type: 'text',
      placeholder: '搜索素材、标签、OCR 文案...'
    });
    searchInput.value = this.searchQuery;
    searchInput.addEventListener('input', (e) => {
      this.searchQuery = e.target.value;
      this.applyFilters();
      this.renderGalleryOnly();
    });

    // Right Header Controls
    const rightHeader = header.createDiv({ cls: 'crisp-visual-header-right' });

    const isPro = this.plugin.licenseManager && this.plugin.licenseManager.isEntitled();
    if (!isPro) {
      const proPill = rightHeader.createEl('button', {
        cls: 'crisp-visual-btn crisp-visual-btn-pro',
        title: '一码解锁 Crisp Visual 全部专业版功能'
      });
      proPill.innerHTML = `<span>✨ 激活 Pro</span>`;
      proPill.addEventListener('click', () => {
        new CrispVisualActivationModal(this.app, this.plugin, () => this.refresh()).open();
      });
    }

    // 1. Ingest Paste Button
    const pasteBtn = rightHeader.createEl('button', { cls: 'crisp-visual-btn', title: '从剪贴板快速导入截图/图片 (Cmd+V)' });
    pasteBtn.innerHTML = `${ICON_PASTE}<span>粘贴</span>`;
    pasteBtn.addEventListener('click', (e) => this.handlePaste(e));

    // 2. Grayscale Toggle Button (黑白)
    const grayBtn = rightHeader.createEl('button', {
      cls: `crisp-visual-btn ${this.isGrayscaleMode ? 'crisp-visual-btn-active' : ''}`,
      title: '切换黑白灰度模式 (观察版面构图节奏与明度对比)'
    });
    grayBtn.innerHTML = `${ICON_GRAYSCALE}<span>黑白</span>`;
    grayBtn.addEventListener('click', () => {
      this.isGrayscaleMode = !this.isGrayscaleMode;
      grayBtn.classList.toggle('crisp-visual-btn-active', this.isGrayscaleMode);
      if (this.galleryContainer) {
        this.galleryContainer.classList.toggle('crisp-visual-grayscale', this.isGrayscaleMode);
      }
    });

    // 3. Random Shuffle Button (漫游)
    const shuffleBtn = rightHeader.createEl('button', { cls: 'crisp-visual-btn', title: '灵感随机漫游 (打乱时间顺序激发选题灵感)' });
    shuffleBtn.innerHTML = `${ICON_SHUFFLE}<span>漫游</span>`;
    shuffleBtn.addEventListener('click', () => {
      for (let i = this.filteredItems.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [this.filteredItems[i], this.filteredItems[j]] = [this.filteredItems[j], this.filteredItems[i]];
      }
      this.renderGalleryOnly();
      new Notice('🎲 已开启视觉灵感随机漫游！');
    });

    // 4. Aspect Ratio Selector
    const ratioSelect = rightHeader.createEl('select', { cls: 'crisp-visual-format-select' });
    [
      { id: 'all', text: '全部比例' },
      { id: '1:1', text: '1:1' },
      { id: '3:4', text: '3:4' },
      { id: '4:3', text: '4:3' },
      { id: '9:16', text: '9:16' },
      { id: '16:9', text: '16:9' },
      { id: 'banner', text: 'Banner' },
      { id: 'long', text: '长图' },
      { id: 'other', text: '其他' }
    ].forEach(r => {
      const opt = ratioSelect.createEl('option', { value: r.id, text: r.text });
      if (this.selectedRatio === r.id) opt.selected = true;
    });
    ratioSelect.addEventListener('change', (e) => {
      this.selectedRatio = e.target.value;
      this.applyFilters();
      this.renderGalleryOnly();
    });

    // 5. Star Rating Selector
    const starSelect = rightHeader.createEl('select', { cls: 'crisp-visual-format-select' });
    [
      { id: 'all', text: '★ 全部星级' },
      { id: '5', text: '★★★★★ 5星' },
      { id: '4', text: '★★★★+ 4星以上' },
      { id: '3', text: '★★★+ 3星以上' }
    ].forEach(s => {
      const opt = starSelect.createEl('option', { value: s.id, text: s.text });
      if (this.selectedStar === s.id) opt.selected = true;
    });
    starSelect.addEventListener('change', (e) => {
      this.selectedStar = e.target.value;
      this.applyFilters();
      this.renderGalleryOnly();
    });

    // 6. Format Selector
    const formatSelect = rightHeader.createEl('select', { cls: 'crisp-visual-format-select' });
    ['all', 'gif', 'png', 'jpg', 'svg', 'webp'].forEach(fmt => {
      const opt = formatSelect.createEl('option', { value: fmt, text: fmt.toUpperCase() });
      if (this.selectedFormat === fmt) opt.selected = true;
    });
    formatSelect.addEventListener('change', (e) => {
      this.selectedFormat = e.target.value;
      this.applyFilters();
      this.renderGalleryOnly();
    });

    // 8. Layout Density Segmented Control (☵ 紧凑 / ☷ 标准 / ▢ 大图)
    const densityGroup = rightHeader.createDiv({ cls: 'crisp-visual-segmented-control' });
    const densityOptions = [
      {
        id: 'compact',
        title: '紧凑小图模式 (多列密集浏览)',
        icon: '<svg viewBox="0 0 24 24" width="13" height="13" fill="currentColor"><rect x="2" y="2" width="5" height="5" rx="1"/><rect x="9.5" y="2" width="5" height="5" rx="1"/><rect x="17" y="2" width="5" height="5" rx="1"/><rect x="2" y="9.5" width="5" height="5" rx="1"/><rect x="9.5" y="9.5" width="5" height="5" rx="1"/><rect x="17" y="9.5" width="5" height="5" rx="1"/><rect x="2" y="17" width="5" height="5" rx="1"/><rect x="9.5" y="17" width="5" height="5" rx="1"/><rect x="17" y="17" width="5" height="5" rx="1"/></svg>'
      },
      {
        id: 'standard',
        title: '标准适中模式 (平衡视图)',
        icon: '<svg viewBox="0 0 24 24" width="13" height="13" fill="currentColor"><rect x="3" y="3" width="7.5" height="7.5" rx="1.5"/><rect x="13.5" y="3" width="7.5" height="7.5" rx="1.5"/><rect x="3" y="13.5" width="7.5" height="7.5" rx="1.5"/><rect x="13.5" y="13.5" width="7.5" height="7.5" rx="1.5"/></svg>'
      },
      {
        id: 'large',
        title: '沉浸大图模式 (高精细节)',
        icon: '<svg viewBox="0 0 24 24" width="13" height="13" fill="currentColor"><rect x="3" y="3" width="18" height="18" rx="2"/></svg>'
      }
    ];

    densityOptions.forEach(opt => {
      const btn = densityGroup.createDiv({
        cls: `crisp-visual-segment-btn ${this.densityMode === opt.id ? 'active' : ''}`,
        title: opt.title
      });
      btn.innerHTML = opt.icon;
      btn.addEventListener('click', async () => {
        this.densityMode = opt.id;
        this.plugin.settings.densityMode = opt.id;
        await this.plugin.saveSettings();
        densityGroup.querySelectorAll('.crisp-visual-segment-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        this.renderGalleryOnly();
      });
    });

    // 9. Refresh Button
    const refreshBtn = rightHeader.createEl('button', { cls: 'crisp-visual-btn', title: '重新扫描并刷新画廊' });
    refreshBtn.innerHTML = `${ICON_REFRESH}<span>刷新</span>`;
    refreshBtn.addEventListener('click', () => this.refresh());

    // 2. Main Body
    const body = container.createDiv({ cls: 'crisp-visual-body' });

    // Sidebar: Dynamic Folder Tree
    const sidebar = body.createDiv({ cls: `crisp-visual-sidebar ${this.isSidebarCollapsed ? 'collapsed' : ''}` });
    if (!this.isSidebarCollapsed) {
      this.renderSidebar(sidebar);
    }

    // Gallery Scroll Container
    this.galleryContainer = body.createDiv({ cls: `crisp-visual-gallery-scroll ${this.isGrayscaleMode ? 'crisp-visual-grayscale' : ''}` });
    this.renderMasonry();
  }

  renderSidebar(sidebar) {
    sidebar.empty();

    // 1. Top Fixed Navigation
    const allRow = sidebar.createDiv({ cls: `crisp-visual-tree-row ${this.selectedFolderId === 'all' && !this.selectedTag ? 'active' : ''}` });
    const allLeft = allRow.createDiv({ cls: 'crisp-visual-tree-left' });
    allLeft.innerHTML = `${ICON_ALL_ASSETS}<span class="crisp-visual-folder-name">全部素材</span>`;
    const allCount = allRow.createDiv({ cls: 'crisp-visual-nav-item-count' });
    allCount.setText(String(this.items.length));
    allRow.addEventListener('click', () => {
      this.selectedFolderId = 'all';
      this.selectedTag = null;
      this.applyFilters();
      this.render();
    });

    const uncatCountNum = this.items.filter(i => !i.folders || i.folders.length === 0).length;
    if (uncatCountNum > 0) {
      const uncatRow = sidebar.createDiv({ cls: `crisp-visual-tree-row ${this.selectedFolderId === 'uncategorized' ? 'active' : ''}` });
      const uncatLeft = uncatRow.createDiv({ cls: 'crisp-visual-tree-left' });
      uncatLeft.innerHTML = `<svg viewBox="0 0 24 24" class="crisp-visual-custom-icon" fill="none" stroke="currentColor" stroke-width="2"><polyline points="22 12 16 12 14 15 10 15 8 12 2 12"/><path d="M5.45 5.11 2 12v6a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-6l-3.45-6.89A2 2 0 0 0 16.76 4H7.24a2 2 0 0 0-1.79 1.11z"/></svg><span class="crisp-visual-folder-name">待整理素材</span>`;
      const uncatCount = uncatRow.createDiv({ cls: 'crisp-visual-nav-item-count' });
      uncatCount.setText(String(uncatCountNum));
      uncatRow.addEventListener('click', () => {
        this.selectedFolderId = 'uncategorized';
        this.selectedTag = null;
        this.applyFilters();
        this.render();
      });
    }

    // 2. Render Folders Section in Sidebar
    if (this.scanner.folders && this.scanner.folders.length > 0) {
      const isFoldersExpanded = !this.isFoldersCollapsed;
      const folderDivider = sidebar.createDiv({ cls: 'crisp-visual-sidebar-divider crisp-visual-sidebar-divider-collapsible' });
      folderDivider.title = this.isFoldersCollapsed ? '点击展开资源目录' : '点击收起资源目录';

      const leftPart = folderDivider.createDiv({ cls: 'crisp-visual-divider-left' });
      const chevron = leftPart.createSpan({ cls: `crisp-visual-chevron ${isFoldersExpanded ? 'expanded' : ''}` });
      chevron.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="m9 18 6-6-6-6"/></svg>`;
      leftPart.createSpan({ text: '资源目录' });

      folderDivider.createSpan({ cls: 'crisp-visual-divider-count', text: String(this.scanner.folders.length) });

      folderDivider.addEventListener('click', () => {
        this.isFoldersCollapsed = !this.isFoldersCollapsed;
        this.renderSidebar(sidebar);
      });

      if (isFoldersExpanded) {
        const treeContainer = sidebar.createDiv({ cls: 'crisp-visual-folder-tree' });

        const renderFolderNode = (f, container, level = 0) => {
          const nodeEl = container.createDiv({ cls: 'crisp-visual-tree-node' });
          const hasChildren = f.children && f.children.length > 0;
          const isExpanded = this.expandedFolders.has(f.id);
          const isSelected = this.selectedFolderId === f.id;

          const row = nodeEl.createDiv({ cls: `crisp-visual-tree-row ${isSelected ? 'active' : ''}` });
          row.style.paddingLeft = `${6 + level * 14}px`;

          const left = row.createDiv({ cls: 'crisp-visual-tree-left' });

          // Chevron
          const chevron = left.createSpan({ cls: `crisp-visual-chevron ${hasChildren ? '' : 'hidden'} ${isExpanded ? 'expanded' : ''}` });
          chevron.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="m9 18 6-6-6-6"/></svg>`;
          if (hasChildren) {
            chevron.addEventListener('click', (e) => {
              e.stopPropagation();
              if (this.expandedFolders.has(f.id)) {
                this.expandedFolders.delete(f.id);
              } else {
                this.expandedFolders.add(f.id);
              }
              this.renderSidebar(sidebar);
            });
          }

          // Folder Color Dot / Icon
          const folderColor = FOLDER_COLOR_MAP[f.iconColor] || '#888888';
          const icon = left.createSpan({ cls: 'crisp-visual-folder-icon' });
          icon.innerHTML = `<svg viewBox="0 0 24 24" fill="${folderColor}" stroke="none"><path d="M4 4c-1.1 0-2 .9-2 2v12c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V8c0-1.1-.9-2-2-2h-8l-2-2H4z"/></svg>`;

          // Folder Name
          const nameEl = left.createSpan({ cls: 'crisp-visual-folder-name' });
          nameEl.setText(f.name);
          nameEl.title = f.name;

          // Recursive Count
          const count = this.items.filter(i => i.allFolderIds && i.allFolderIds.has(f.id)).length;
          const countEl = row.createDiv({ cls: 'crisp-visual-nav-item-count' });
          countEl.setText(String(count));

          row.addEventListener('click', () => {
            this.selectedFolderId = f.id;
            this.applyFilters();
            this.render();
          });

          if (hasChildren && isExpanded) {
            const childrenContainer = nodeEl.createDiv({ cls: 'crisp-visual-tree-children' });
            for (const child of f.children) {
              renderFolderNode(child, childrenContainer, level + 1);
            }
          }
        };

        for (const f of this.scanner.folders) {
          renderFolderNode(f, treeContainer, 0);
        }
      }
    }

    // 3. Render Tags Section in Sidebar
    const tagCountMap = new Map();
    this.items.forEach(i => {
      if (i.tags && Array.isArray(i.tags)) {
        i.tags.forEach(t => {
          if (t) tagCountMap.set(t, (tagCountMap.get(t) || 0) + 1);
        });
      }
    });

    if (tagCountMap.size > 0) {
      const isExpanded = !this.isTagsCollapsed;
      const tagDivider = sidebar.createDiv({ cls: 'crisp-visual-sidebar-divider crisp-visual-sidebar-divider-collapsible' });
      tagDivider.title = this.isTagsCollapsed ? '点击展开所有标签' : '点击收起所有标签';

      const leftPart = tagDivider.createDiv({ cls: 'crisp-visual-divider-left' });
      const chevron = leftPart.createSpan({ cls: `crisp-visual-chevron ${isExpanded ? 'expanded' : ''}` });
      chevron.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="m9 18 6-6-6-6"/></svg>`;
      leftPart.createSpan({ text: '标签分类' });

      tagDivider.createSpan({ cls: 'crisp-visual-divider-count', text: String(tagCountMap.size) });

      tagDivider.addEventListener('click', () => {
        this.isTagsCollapsed = !this.isTagsCollapsed;
        this.renderSidebar(sidebar);
      });

      if (isExpanded) {
        const tagContainer = sidebar.createDiv({ cls: 'crisp-visual-tag-list' });
        const sortedTags = Array.from(tagCountMap.entries()).sort((a, b) => b[1] - a[1]);
        
        sortedTags.forEach(([tag, count]) => {
          const tagRow = tagContainer.createDiv({
            cls: `crisp-visual-tree-row ${this.selectedTag === tag ? 'active' : ''}`
          });
          const left = tagRow.createDiv({ cls: 'crisp-visual-tree-left' });
          left.innerHTML = `<span class="crisp-visual-tag-hash">#</span><span class="crisp-visual-folder-name">${tag}</span>`;
          const countEl = tagRow.createDiv({ cls: 'crisp-visual-nav-item-count' });
          countEl.setText(String(count));
          
          tagRow.addEventListener('click', (e) => {
            e.stopPropagation();
            if (this.selectedTag === tag) {
              this.selectedTag = null;
            } else {
              this.selectedTag = tag;
            }
            this.applyFilters();
            this.render();
          });
        });
      }
    }
  }

  renderGalleryOnly() {
    if (this.galleryContainer) {
      this.galleryContainer.empty();
      this.renderMasonry();
    }
  }

  renderMasonry() {
    if (!this.plugin.settings.mediaRoot || !fs.existsSync(this.plugin.settings.mediaRoot)) {
      const empty = this.galleryContainer.createDiv({ cls: 'crisp-visual-empty-state' });
      empty.innerHTML = `
        <div class="crisp-visual-empty-icon">${ICON_ALL_ASSETS}</div>
        <div style="font-weight: 600; font-size: 15px;">欢迎使用 Crisp Visual 视觉资产工作台</div>
        <div style="font-size: 12px; color: var(--text-muted); max-width: 420px; text-align: center; line-height: 1.5; margin: 8px 0 16px;">
          当前尚未绑定 Eagle 素材库路径。你可以点击下方按钮一键自动探测，或前往插件设置手动配置。
        </div>
      `;
      const detectBtn = empty.createEl('button', { cls: 'crisp-visual-btn crisp-visual-btn-accent', text: '🔍 一键自动探测 Eagle 素材库' });
      detectBtn.addEventListener('click', async () => {
        const found = discoverEagleLibraryPath(this.app);
        if (found) {
          this.plugin.settings.mediaRoot = found;
          await this.plugin.saveSettings();
          new Notice(`✅ 已成功探测并绑定素材库：${path.basename(path.dirname(found))}`);
          await this.refresh();
        } else {
          new Notice('ℹ️ 未能自动发现 .library 目录，请前往设置面板手动配置路径');
        }
      });
      return;
    }

    if (!this.filteredItems || this.filteredItems.length === 0) {
      const empty = this.galleryContainer.createDiv({ cls: 'crisp-visual-empty-state' });
      empty.innerHTML = `
        <div class="crisp-visual-empty-icon">${ICON_ALL_ASSETS}</div>
        <div style="font-weight: 500; font-size: 14px;">没有找到符合条件的视觉素材</div>
        <div style="font-size: 12px; color: var(--text-muted);">尝试调整筛选条件、星级评分，或按 Cmd+V 粘贴新素材</div>
      `;
      return;
    }

    const masonry = this.galleryContainer.createDiv({ cls: `crisp-visual-masonry density-${this.densityMode}` });

    this.filteredItems.forEach(item => {
      const card = masonry.createDiv({ cls: 'crisp-visual-card' });
      card.setAttribute('draggable', 'true');

      // Drag & Drop to Markdown Editor or Canvas
      card.addEventListener('dragstart', (e) => {
        const insertSyntax = this.generateInsertSyntax(item);
        e.dataTransfer.setData('text/plain', insertSyntax);
        e.dataTransfer.setData('text/uri-list', `file://${item.filePath}`);
        e.dataTransfer.effectAllowed = 'copy';
      });

      // Badges (GIF / Resolution / Stars)
      const badgeGroup = card.createDiv({ cls: 'crisp-visual-badge-group' });
      if (item.ext === 'gif') {
        const gifBadge = badgeGroup.createDiv({ cls: 'crisp-visual-badge crisp-visual-badge-gif' });
        gifBadge.setText('GIF');
      } else if (item.ext === 'svg') {
        const svgBadge = badgeGroup.createDiv({ cls: 'crisp-visual-badge crisp-visual-badge-svg' });
        svgBadge.setText('SVG');
      }

      if (item.width > 0 && item.height > 0) {
        const resBadge = badgeGroup.createDiv({ cls: 'crisp-visual-badge' });
        resBadge.setText(`${item.width}×${item.height}`);
      }

      // Display Star Rating Badge on Card if Rated
      if (item.star && item.star > 0) {
        const starBadge = badgeGroup.createDiv({ cls: 'crisp-visual-badge crisp-visual-badge-star' });
        starBadge.setText('★'.repeat(item.star));
      }

      // Card Quick Actions Hover Bar (Clean Vector SVGs)
      const actions = card.createDiv({ cls: 'crisp-visual-card-actions' });

      const copyBtn = actions.createEl('button', { cls: 'crisp-visual-action-btn', title: '插入到当前笔记' });
      copyBtn.innerHTML = ICON_INSERT_NOTE;
      copyBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        this.insertToActiveNote(item);
      });

      const eagleBtn = actions.createEl('button', { cls: 'crisp-visual-action-btn', title: '在 Eagle 中打开' });
      eagleBtn.innerHTML = ICON_OPEN_EAGLE;
      eagleBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        window.open(item.eagleUri);
      });

      // Image Container
      const imgWrap = card.createDiv({ cls: 'crisp-visual-img-wrap' });
      const img = imgWrap.createEl('img', { cls: 'crisp-visual-img' });
      img.alt = item.name;

      attachImageSrc(img, item.thumbnailPath || item.filePath, item.ext);

      // Card Footer
      const footer = card.createDiv({ cls: 'crisp-visual-card-footer' });
      const nameEl = footer.createDiv({ cls: 'crisp-visual-card-name' });
      nameEl.setText(item.name);
      nameEl.title = item.name;

      const metaEl = footer.createDiv({ cls: 'crisp-visual-card-meta' });
      const sizeText = item.size > 1024 * 1024 
        ? `${(item.size / 1024 / 1024).toFixed(1)} MB` 
        : `${(item.size / 1024).toFixed(0)} KB`;
      metaEl.setText(`${item.ext.toUpperCase()} · ${sizeText}`);

      // Click to open Inspector
      card.addEventListener('click', () => {
        this.openInspector(item);
      });

      // Right Click Context Menu
      card.addEventListener('contextmenu', (e) => {
        e.preventDefault();
        this.showContextMenu(e, item);
      });
    });

    if (this.isFreeCapped) {
      const banner = this.galleryContainer.createDiv({ cls: 'crisp-visual-pro-banner' });
      banner.innerHTML = `
        <div class="crisp-visual-pro-banner-icon">✨</div>
        <div class="crisp-visual-pro-banner-content">
          <div class="crisp-visual-pro-banner-title">解锁全部 ${this.totalFilteredCount} 张素材与专业版功能</div>
          <div class="crisp-visual-pro-banner-desc">免费版仅预览前 20 张素材。激活后即可解锁全库海量浏览、本地离线 Vision OCR 搜图、Cmd+V 秒存入库及 ANKS 认知卡片。</div>
        </div>
      `;
      const actBtn = banner.createEl('button', { cls: 'crisp-visual-btn crisp-visual-btn-accent', text: '🔑 输入授权码' });
      actBtn.addEventListener('click', () => {
        new CrispVisualActivationModal(this.app, this.plugin, () => this.refresh()).open();
      });
    }
  }

  generateInsertSyntax(item) {
    const encodedPath = encodeURI(item.filePath);
    const mode = this.plugin.settings.insertFormat;

    if (mode === 'standard_markdown') {
      return `![${item.name}](file://${encodedPath})`;
    } else if (mode === 'clickable_embed') {
      return `[![${item.name}](file://${encodedPath})](${item.eagleUri})`;
    } else {
      return `[查看素材 → ${item.name}](${item.eagleUri})`;
    }
  }

  insertToActiveNote(item) {
    const syntax = this.generateInsertSyntax(item);
    const activeLeaf = this.app.workspace.activeLeaf;
    if (activeLeaf && activeLeaf.view && activeLeaf.view.editor) {
      activeLeaf.view.editor.replaceSelection(`\n${syntax}\n`);
      new Notice(`已将素材插入到当前笔记！`);
    } else {
      navigator.clipboard.writeText(syntax);
      new Notice(`已复制 Markdown 语法到剪贴板！`);
    }
  }

  showContextMenu(event, item) {
    const menu = new Menu();

    menu.addItem(i => i
      .setTitle('插入到当前笔记')
      .setIcon('clipboard')
      .onClick(() => this.insertToActiveNote(item))
    );

    menu.addItem(i => i
      .setTitle('绑定到当前选题 (CNT-xxx)')
      .setIcon('pin')
      .onClick(() => this.bindToActiveTopic(item))
    );

    menu.addItem(i => i
      .setTitle('提取/刷新本地 OCR 文案')
      .setIcon('scan-text')
      .onClick(async () => {
        if (!this.plugin.licenseManager || !this.plugin.licenseManager.isEntitled()) {
          new Notice('🔒 本地 Vision OCR 识别为 Crisp Pro 专业版功能');
          new CrispVisualActivationModal(this.app, this.plugin, () => this.refresh()).open();
          return;
        }
        new Notice('[Crisp Visual] 正在进行本地 Vision OCR 识别...');
        const text = await this.scanner.runOCR(item);
        if (text) {
          new Notice(`OCR 识别完成 (${text.length} 字)，已建立即席搜索索引！`);
        } else {
          new Notice('未在画面中识别到清晰文本');
        }
      })
    );

    menu.addSeparator();

    menu.addItem(i => i
      .setTitle('复制 Markdown 可点击语法')
      .setIcon('link')
      .onClick(() => {
        navigator.clipboard.writeText(this.generateInsertSyntax(item));
        new Notice('已复制 Markdown 语法！');
      })
    );

    menu.addItem(i => i
      .setTitle('复制 Eagle 协议链接')
      .setIcon('external-link')
      .onClick(() => {
        navigator.clipboard.writeText(item.eagleUri);
        new Notice('已复制 Eagle URI！');
      })
    );

    menu.addItem(i => i
      .setTitle('创建 ANKS RAW 认知卡片')
      .setIcon('file-plus')
      .onClick(() => this.createRawCard(item))
    );

    menu.addItem(i => i
      .setTitle('在 Finder 中定位')
      .setIcon('folder')
      .onClick(() => {
        const { shell } = require('electron');
        shell.showItemInFolder(item.filePath);
      })
    );

    menu.showAtMouseEvent(event);
  }

  async bindToActiveTopic(item) {
    if (!this.plugin.licenseManager || !this.plugin.licenseManager.isEntitled()) {
      new Notice('🔒 选题双向绑定为 Crisp Pro 专业版功能');
      new CrispVisualActivationModal(this.app, this.plugin, () => this.refresh()).open();
      return;
    }

    const activeFile = this.app.workspace.getActiveFile();
    if (!activeFile) {
      new Notice('请先打开一篇选题笔记（如 CNT-xxx 选题文稿）');
      return;
    }

    try {
      const content = await this.app.vault.read(activeFile);
      const syntax = this.generateInsertSyntax(item);
      const updatedContent = content.replace(/^---\n([\s\S]*?)\n---/, (match, fm) => {
        if (!fm.includes('eagle:')) {
          return `---\n${fm}\neagle:\n  items:\n    - id: "${item.id}"\n      name: "${item.name}"\n      uri: "${item.eagleUri}"\n---`;
        } else {
          return match;
        }
      });

      if (updatedContent !== content) {
        await this.app.vault.modify(activeFile, updatedContent);
      }

      new Notice(`已成功将素材绑定到选题《${activeFile.basename}》！`);
    } catch (e) {
      new Notice(`绑定选题失败: ${e.message}`);
    }
  }

  async createRawCard(item) {
    if (!this.plugin.licenseManager || !this.plugin.licenseManager.isEntitled()) {
      new Notice('🔒 ANKS 认知卡片生成为 Crisp Pro 专业版功能');
      new CrispVisualActivationModal(this.app, this.plugin, () => this.refresh()).open();
      return;
    }

    const today = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    const cardId = `RAW-${today}-${item.id}`;
    const cardTitle = item.name;
    const destRel = `Topics/self-media/raw/inbox/${cardId}.md`;
    
    const vaultPath = this.app.vault.adapter.getBasePath ? this.app.vault.adapter.getBasePath() : '';
    const fullPath = path.join(vaultPath, destRel);

    const content = `---
id: "${cardId}"
type: "raw"
topic: "self-media"
owner: "topic:self-media"
title: "${cardTitle}"
status: "inbox"
source_type: "visual"
source_url: "${item.url || ''}"
created_at: "${new Date().toISOString().slice(0, 16).replace('T', ' ')}"
routing_confidence: 1
routing_reason: "Crisp Visual Ingest"
eagle:
  item_id: "${item.id}"
  ext: "${item.ext}"
  dimensions: "${item.width}x${item.height}"
  size_bytes: ${item.size}
  star: ${item.star || 0}
  uri: "${item.eagleUri}"
---

# 视觉素材卡片：${cardTitle}

> 💡 **双向唤起**：点击下方图片可在 Eagle 中秒开定位。

[![${cardTitle}](file://${encodeURI(item.filePath)})](${item.eagleUri})

---

## 视觉元数据
- **素材 ID**：\`${item.id}\`
- **规格尺寸**：\`${item.ext.toUpperCase()} (${item.width} × ${item.height}, ${(item.size / 1024).toFixed(1)} KB)\`
- **主要色调**：\`${item.primaryHex} (${item.primaryColorGroup})\`
- **星级评分**：\`${'★'.repeat(item.star || 0) || '未评分'}\`

---

## OCR 识别文案 (Recognized Text)
\`\`\`text
${item.ocrText || item.annotation || '（暂无提取文案）'}
\`\`\`

---

## 观察与思考 (Observation & Context)
- **视觉特征**：
- **为什么收藏**：
- **潜在应用场景**：
`;

    try {
      if (!fs.existsSync(path.dirname(fullPath))) {
        fs.mkdirSync(path.dirname(fullPath), { recursive: true });
      }
      fs.writeFileSync(fullPath, content, 'utf-8');
      new Notice(`🎉 已成功创建 ANKS 认知卡片：${cardId}.md`);
      
      const tfile = this.app.vault.getAbstractFileByPath(destRel);
      if (tfile) {
        this.app.workspace.getLeaf(true).openFile(tfile);
      }
    } catch (err) {
      new Notice(`❌ 生成卡片失败: ${err.message}`);
    }
  }

  openInspector(initialItem) {
    let currentItem = initialItem;
    const overlay = document.body.createDiv({ cls: 'crisp-visual-inspector-overlay' });

    // Floating Navigation Buttons (Previous & Next)
    const prevBtn = overlay.createEl('button', {
      cls: 'crisp-visual-inspector-nav-btn crisp-visual-nav-prev',
      title: '上一张 (← 方向键)'
    });
    prevBtn.style.cssText = 'background: var(--interactive-accent) !important; color: #ffffff !important; border: none !important; box-shadow: 0 4px 16px rgba(0,0,0,0.4) !important;';
    prevBtn.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="#ffffff" stroke-width="2.5"><path d="m15 18-6-6 6-6"/></svg>`;

    const nextBtn = overlay.createEl('button', {
      cls: 'crisp-visual-inspector-nav-btn crisp-visual-nav-next',
      title: '下一张 (→ 方向键)'
    });
    nextBtn.style.cssText = 'background: var(--interactive-accent) !important; color: #ffffff !important; border: none !important; box-shadow: 0 4px 16px rgba(0,0,0,0.4) !important;';
    nextBtn.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="#ffffff" stroke-width="2.5"><path d="m9 18 6-6-6-6"/></svg>`;

    const card = overlay.createDiv({ cls: 'crisp-visual-inspector-card' });

    // Close logic
    const closeInspector = () => {
      window.removeEventListener('keydown', handleKey);
      overlay.remove();
    };

    overlay.addEventListener('click', (e) => {
      if (e.target === overlay) closeInspector();
    });

    const renderInspectorContent = (item) => {
      currentItem = item;
      card.empty();

      // Header
      const header = card.createDiv({ cls: 'crisp-visual-inspector-header' });
      const titleBadge = header.createDiv({ cls: 'crisp-visual-title-badge' });
      titleBadge.innerHTML = `${ICON_INSPECTOR_HEADER}<span>${item.name}</span>`;

      const closeBtn = header.createEl('button', { cls: 'crisp-visual-btn', text: '✕ 关闭' });
      closeBtn.addEventListener('click', () => closeInspector());

      // Content (Flex row: Image Left, Metadata Right)
      const content = card.createDiv({ cls: 'crisp-visual-inspector-content' });

      // Left: Image Preview
      const imgPane = content.createDiv({ cls: 'crisp-visual-inspector-img-pane' });
      const img = imgPane.createEl('img');
      img.alt = item.name;
      attachImageSrc(img, item.filePath, item.ext);

      // Right: Metadata & Actions
      const metaPane = content.createDiv({ cls: 'crisp-visual-inspector-meta-pane' });

      const createMetaRow = (label, val) => {
        const row = metaPane.createDiv({ cls: 'crisp-visual-meta-row' });
        row.createDiv({ cls: 'crisp-visual-meta-label', text: label });
        row.createDiv({ cls: 'crisp-visual-meta-val', text: val });
        return row;
      };

      createMetaRow('素材名称', item.name);
      createMetaRow('文件规格', `${item.ext.toUpperCase()} · ${item.width} × ${item.height} px`);
      createMetaRow('文件体积', item.size > 1024 * 1024 ? `${(item.size / 1024 / 1024).toFixed(2)} MB` : `${(item.size / 1024).toFixed(1)} KB`);
      createMetaRow('所属目录', item.foldersNamed.join(', ') || '未分类');
      createMetaRow('标签 Tags', item.tags.join(', ') || '无');

      // Star Rating on Inspector (Right Pane)
      const starRow = metaPane.createDiv({ cls: 'crisp-visual-meta-row' });
      starRow.createDiv({ cls: 'crisp-visual-meta-label', text: '星级评分 (点击评分)' });
      const starRater = starRow.createDiv({ cls: 'crisp-visual-inspector-star-rater' });
      [1, 2, 3, 4, 5].forEach(starNum => {
        const s = starRater.createDiv({
          cls: `crisp-visual-star-item ${(item.star || 0) >= starNum ? 'active' : ''}`,
          title: `${starNum} 星`
        });
        s.innerHTML = `<svg viewBox="0 0 24 24" class="crisp-visual-star-svg"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2" /></svg>`;
        s.addEventListener('click', async () => {
          if (!this.plugin.licenseManager || !this.plugin.licenseManager.isEntitled()) {
            new Notice('🔒 星级评分修改与持久化为 Crisp Pro 专业版功能');
            new CrispVisualActivationModal(this.app, this.plugin, () => this.refresh()).open();
            return;
          }
          const newStar = item.star === starNum ? 0 : starNum;
          await this.scanner.updateItemStar(item, newStar);
          this.renderGalleryOnly();
          // Update stars visually in inspector
          const stars = starRater.querySelectorAll('.crisp-visual-star-item');
          stars.forEach((st, idx) => {
            st.classList.toggle('active', idx < newStar);
          });
          new Notice(`已更新评分：${newStar} 星`);
        });
      });

      // OCR Text Block
      const ocrRow = metaPane.createDiv({ cls: 'crisp-visual-meta-row' });
      const ocrLabelWrap = ocrRow.createDiv({ cls: 'crisp-visual-ocr-header' });
      ocrLabelWrap.createDiv({ cls: 'crisp-visual-meta-label', text: 'OCR 画面提取文案' });
      const runOcrBtn = ocrLabelWrap.createEl('button', { cls: 'crisp-visual-ocr-btn', text: '识别/刷新' });
      
      const ocrVal = ocrRow.createDiv({ cls: 'crisp-visual-ocr-box' });
      ocrVal.setText(item.ocrText || item.annotation || '（未识别，点击右上角识别）');
      
      runOcrBtn.addEventListener('click', async () => {
        if (!this.plugin.licenseManager || !this.plugin.licenseManager.isEntitled()) {
          new Notice('🔒 本地 Vision OCR 识别为 Crisp Pro 专业版功能');
          new CrispVisualActivationModal(this.app, this.plugin, () => this.refresh()).open();
          return;
        }
        runOcrBtn.setText('识别中...');
        new Notice('[Crisp Visual] 正在进行本地 Vision OCR 识别...');
        const text = await this.scanner.runOCR(item);
        if (text) {
          ocrVal.setText(text);
          runOcrBtn.setText('✓ 成功');
          new Notice(`OCR 提取成功 (${text.length} 字)，已建立即席搜索索引！`);
        } else {
          runOcrBtn.setText('无文字');
          new Notice('未在画面中识别到清晰文字');
        }
      });

      // Color Palette Chips with Instant Copy HEX on Click
      if (item.palettes && item.palettes.length > 0) {
        const colorRow = metaPane.createDiv({ cls: 'crisp-visual-meta-row' });
        colorRow.createDiv({ cls: 'crisp-visual-meta-label', text: '主色彩分布 (点击复制 HEX)' });
        const chips = colorRow.createDiv({ cls: 'crisp-visual-palette-chips' });
        item.palettes.forEach(p => {
          if (p.color && p.color.length === 3) {
            const hex = rgbToHex(p.color[0], p.color[1], p.color[2]);
            const chip = chips.createDiv({ cls: 'crisp-visual-palette-chip' });
            chip.style.background = hex;
            chip.title = `点击复制 ${hex} (${p.ratio}%)`;
            chip.addEventListener('click', () => {
              navigator.clipboard.writeText(hex);
              new Notice(`已复制色号：${hex}`);
            });
          }
        });
      }

      // Action Buttons
      const actions = metaPane.createDiv({ cls: 'crisp-visual-inspector-actions' });
      const insertBtn = actions.createEl('button', { cls: 'crisp-visual-btn crisp-visual-btn-accent' });
      insertBtn.innerHTML = `${ICON_INSERT_NOTE}<span>插入到当前笔记</span>`;
      insertBtn.addEventListener('click', () => {
        this.insertToActiveNote(item);
        closeInspector();
      });

      const cardBtn = actions.createEl('button', { cls: 'crisp-visual-btn' });
      cardBtn.innerHTML = `${ICON_GENERATE_ANKS}<span>生成 ANKS 认知卡片</span>`;
      cardBtn.addEventListener('click', () => {
        this.createRawCard(item);
        closeInspector();
      });

      const openEagleBtn = actions.createEl('button', { cls: 'crisp-visual-btn' });
      openEagleBtn.innerHTML = `${ICON_OPEN_EAGLE}<span>在 Eagle 桌面端打开</span>`;
      openEagleBtn.addEventListener('click', () => {
        window.open(item.eagleUri);
      });
    };

    const navigate = (direction) => {
      if (!this.filteredItems || this.filteredItems.length === 0) return;
      let idx = this.filteredItems.findIndex(i => i.id === currentItem.id);
      if (idx === -1) idx = 0;
      let nextIdx = idx + direction;
      if (nextIdx < 0) nextIdx = this.filteredItems.length - 1;
      if (nextIdx >= this.filteredItems.length) nextIdx = 0;
      renderInspectorContent(this.filteredItems[nextIdx]);
    };

    prevBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      navigate(-1);
    });

    nextBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      navigate(1);
    });

    const handleKey = (e) => {
      if (e.key === 'Escape') {
        closeInspector();
      } else if (e.key === 'ArrowLeft') {
        navigate(-1);
      } else if (e.key === 'ArrowRight') {
        navigate(1);
      }
    };

    window.addEventListener('keydown', handleKey);

    renderInspectorContent(initialItem);
  }
}

function renderAboutCard(container) {
  const card = container.createEl('section', { cls: 'crisp-visual-about' });
  card.createEl('h3', { cls: 'crisp-visual-about__title', text: '关于 Crisp Visual' });
  card.createEl('p', {
    cls: 'crisp-visual-about__description',
    text: '面向 Obsidian 的数字资产管理 (DAM) 与灵感引擎。无缝直连 Eagle 本地素材库，提供流式极速加载、跨库零摩擦拖拽采集、智能布局与 ANKS 认知卡片反哺。'
  });
  const byline = card.createEl('p', { cls: 'crisp-visual-about__author' });
  byline.createSpan({ text: '作者：' });
  const author = byline.createEl('a', {
    cls: 'crisp-visual-about__author-link',
    text: '小红书 letschips',
    href: 'https://xhslink.cn/m/3MwtKu4822b'
  });
  author.setAttr('target', '_blank');
  author.setAttr('rel', 'noopener noreferrer');
}

/**
 * Settings Tab
 */
class CrispVisualSettingTab extends PluginSettingTab {
  constructor(app, plugin) {
    super(app, plugin);
    this.plugin = plugin;
    this.licenseDraft = plugin.settings?.licenseCode || '';
  }

  display() {
    const { containerEl } = this;
    containerEl.empty();
    containerEl.createEl('h2', { text: 'Crisp Visual 设置' });

    // 1. Render About Card (Author & Info)
    renderAboutCard(containerEl);

    // 2. Software License Group (一码激活所有 Crisp 插件)
    new Setting(containerEl)
      .setName('软件授权')
      .setHeading();

    const statusSetting = new Setting(containerEl)
      .setName('当前激活状态');

    const licenseStatus = this.plugin.licenseManager ? this.plugin.licenseManager.getStatus() : { valid: false };
    if (licenseStatus.valid && licenseStatus.payload) {
      const owner = licenseStatus.payload.userName || "Crisp 用户";
      const product = licenseStatus.payload.product || "Crisp Suite";
      const expiry = licenseStatus.payload.expiresAt
        ? `，到期时间: ${String(licenseStatus.payload.expiresAt).split("T")[0]}`
        : "";
      const verification = licenseStatus.source === "offline" ? "离线验证" : "在线验证";
      statusSetting.setDesc(`✅ 已激活（${verification} · ${product} · 授权给: ${owner}${expiry}）`);
      
      statusSetting.addButton(btn => btn
        .setButtonText('清除激活')
        .setWarning()
        .onClick(async () => {
          this.plugin.settings.licenseCode = '';
          this.plugin.licenseManager.status = { valid: false, reason: "已手动清除激活" };
          this.licenseDraft = '';
          await this.plugin.saveSettings();
          new Notice('已清除当前插件激活信息');
          this.display();
        }));
    } else if (this.plugin.settings.licenseCode) {
      statusSetting.setDesc(`❌ 未激活（${licenseStatus.reason || "授权码无效"}）`);
    } else {
      statusSetting.setDesc('❌ 未激活（支持 Crisp Suite 一码激活所有插件）');
    }

    if (!licenseStatus.valid) {
      new Setting(containerEl)
        .setName('输入授权码')
        .setDesc('一码激活所有 Crisp 插件（支持 Crisp Suite / Crisp Visual 授权码）')
        .addText(text => {
          text.inputEl.type = 'password';
          text
            .setPlaceholder('粘贴 Crisp 授权码 (xxxx.xxxx)...')
            .setValue(this.licenseDraft || this.plugin.settings.licenseCode)
            .onChange(val => {
              this.licenseDraft = val.trim();
            });
        })
        .addButton(btn => btn
          .setButtonText('激活 / 验证')
          .setCta()
          .onClick(async () => {
            btn.setDisabled(true);
            btn.setButtonText('验证中...');
            const res = await this.plugin.activateLicense(this.licenseDraft);
            if (res.valid) {
              new Notice('🎉 Crisp Visual 激活成功！');
            } else {
              new Notice(`❌ 激活失败: ${res.reason || "未知错误"}`);
            }
            this.display();
          }));
    }

    // 3. Media Library & Core Settings
    new Setting(containerEl)
      .setName('媒体库与通用配置')
      .setHeading();

    const mediaSetting = new Setting(containerEl)
      .setName('外部媒体库路径 (Media Root Path)')
      .setDesc('指定外部 Eagle 资源库的 images 目录（例如 ANKS.library/images，不占用 iCloud 同步空间）');

    mediaSetting.addText(text => text
      .setPlaceholder('/path/to/YourLibrary.library/images')
      .setValue(this.plugin.settings.mediaRoot)
      .onChange(async (val) => {
        this.plugin.settings.mediaRoot = val.trim();
        await this.plugin.saveSettings();
      }));

    mediaSetting.addButton(btn => btn
      .setButtonText('自动探测')
      .setTooltip('自动扫描 Vault 及其上层目录中的 Eagle 素材库')
      .onClick(async () => {
        const found = discoverEagleLibraryPath(this.app);
        if (found) {
          this.plugin.settings.mediaRoot = found;
          await this.plugin.saveSettings();
          new Notice(`已成功探测并绑定素材库：${path.basename(path.dirname(found))}`);
          this.display();
        } else {
          new Notice('未能在 Vault 目录树中发现 .library，请手动输入路径');
        }
      }));

    new Setting(containerEl)
      .setName('默认插入语法 (Insert Format)')
      .setDesc('拖拽或点击插入图片时的默认 Markdown 格式')
      .addDropdown(drop => drop
        .addOption('clickable_embed', '可点击跳转的 Markdown 图片 [![Alt](file://)](eagle://)')
        .addOption('standard_markdown', '标准 Markdown 图片 ![Alt](file://)')
        .addOption('raw_link', '纯超链接 [查看素材](eagle://)')
        .setValue(this.plugin.settings.insertFormat)
        .onChange(async (val) => {
          this.plugin.settings.insertFormat = val;
          await this.plugin.saveSettings();
        }));
  }
}

/**
 * Main Plugin Entry
 */
module.exports = class CrispVisualPlugin extends Plugin {
  async onload() {
    console.log('[Crisp Visual] Loading plugin v0.2.0...');
    await this.loadSettings();

    // Initialize License Manager & Auto-inherit from Crisp Suite
    this.licenseManager = new CrispVisualLicenseManager(this.app, this);
    this.licenseManager.verify().catch(() => {});

    try {
      addIcon('crisp-visual-icon', CRISP_VISUAL_SVG);
    } catch (e) {
      console.warn('[Crisp Visual] Failed to register custom icon:', e);
    }

    // Register View
    this.registerView(
      CRISP_VISUAL_VIEW_TYPE,
      (leaf) => new CrispVisualView(leaf, this)
    );

    // Add Ribbon Icon
    this.addRibbonIcon('crisp-visual-icon', 'Crisp Visual (画廊)', () => {
      this.activateView();
    });

    // Add Commands
    this.addCommand({
      id: 'open-crisp-visual-gallery',
      name: '打开视觉资产画廊',
      callback: () => this.activateView()
    });

    this.addCommand({
      id: 'crisp-visual-paste-clipboard',
      name: '从系统剪贴板快速导入图片素材',
      callback: async () => {
        const leaves = this.app.workspace.getLeavesOfType(CRISP_VISUAL_VIEW_TYPE);
        if (leaves.length > 0) {
          leaves[0].view.handlePaste();
        } else {
          await this.activateView();
          setTimeout(() => {
            const l = this.app.workspace.getLeavesOfType(CRISP_VISUAL_VIEW_TYPE);
            if (l.length > 0) l[0].view.handlePaste();
          }, 300);
        }
      }
    });

    // Add Settings Tab
    this.addSettingTab(new CrispVisualSettingTab(this.app, this));
  }

  onunload() {
    console.log('[Crisp Visual] Unloading plugin.');
  }

  async activateLicense(code) {
    return await this.licenseManager.verify(code);
  }

  async loadSettings() {
    this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
    if (!this.settings.mediaRoot) {
      const autoDiscovered = discoverEagleLibraryPath(this.app);
      if (autoDiscovered) {
        this.settings.mediaRoot = autoDiscovered;
      }
    }
  }

  async saveSettings() {
    await this.saveData(this.settings);
  }

  async activateView() {
    const { workspace } = this.app;
    let leaf = workspace.getLeavesOfType(CRISP_VISUAL_VIEW_TYPE)[0];

    if (!leaf) {
      leaf = workspace.getRightLeaf ? workspace.getRightLeaf(false) : null;
      if (!leaf) leaf = workspace.getLeaf(true);
      await leaf.setViewState({
        type: CRISP_VISUAL_VIEW_TYPE,
        active: true
      });
    }

    workspace.revealLeaf(leaf);
  }
};
